
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    //deskInfo进入游戏获得的服务端数据
    init(deskInfo,gameId,gameJackpot){
        cc.log(deskInfo)

        this._freeGameWheel = deskInfo.freeGameWheel;
        this._storeInfo = deskInfo.storeInfo;
        this._collectInfos = deskInfo.collectInfos;
        this._watermarkInfo = deskInfo.watermarkInfo;

        if(deskInfo.freeGameInfo){
            this._freeMult = deskInfo.freeGameInfo.mult;
        }

        this._freeWinCoin =  deskInfo.freeWinCoin;

        this._super(deskInfo,gameId,gameJackpot);
    },

    //重写接收旋转消息
    OnRcvNetSpine(msg){
        cc.log(msg)

        if(msg.code == 200){

            this._freeGameWheel = msg.freeGameWheel;
            this._storeInfo = msg.storeInfo;
            this._watermarkInfo = msg.watermarkInfo;
            this._wildMult = msg.wildMult;

            this._freeWinCoin = msg.freeWinCoin;


            if(msg.collectInfo){
                this.setCollectInfos(this.GetBetIdx(), msg.collectInfo)
            }
        }

        //----------
        // msg.currDiamond = {idx:25, type:1}

        this._super(msg);
    },


    setPopupScript(scp){
        this._popScp = scp;
    },
    getPopupScript(){
        return this._popScp;
    },

    setFreeWheelScript(scp){
        this._freeWheelScp = scp;
    },
    getFreeWheelScript(){
        return this._freeWheelScp;
    },

    setStoreScript(scp){
        this._storeScp = scp
    },
    getStoreScript(){
        return this._storeScp;
    },

    getNeedBet(){
        return this._deskInfo.needBet
    },

    getCollectInfos(){
        return this._collectInfos
    },
    setCollectInfos(lv, info){
        this._collectInfos[lv-1] = info;
    },

    setStoreInfo(val){
        this._storeInfo = val;
    },
    getStoreInfo(){
        return this._storeInfo;
    },

    getWatermarkInfo(){
        return this._watermarkInfo;
    },

    setFreeMult(val){
        this._freeMult = val;
    },
    getFreeMult(){
        return this._freeMult;
    },

    setFreeGameWheel(val){
        this._freeGameWheel = val;
    },
    getFreeGameWheel(){
        return this._freeGameWheel;
    },

    getWildMult(){
        return this._wildMult;
    },

    setIsFreeGame(val){
        this._isFreeGame = val;
    },
    isFreeGame(){
        return this._isFreeGame;
    },

    getFreeWinCoin(){
        return this._freeWinCoin;
    },


    // update (dt) {},
});
