

let WheelItemType = {
    Jackpot : 1,  // grand
    Blue    : 2,  // 蓝色
    Purple  : 3,  // 紫色
    Red     : 4,  // 红色
    FreeGame: 5,  // 单纯的免费游戏
};

cc.Class({
    extends: cc.Component,
    properties:{
        speed: {
            default: 1,
            tooltip: "旋转速度"
        },
        maxSpeed: {
            default: 30,
            tooltip: "最大速度",
        },
        count: {
            default: 3,
            tooltip: "需要转几轮",
        },
        minSpeed: {
            default: 1,
            tooltip: "最小速度"
        },
        speedOffset: {
            default: 0.25,
            tooltip: "速度变化值",
        },
        //
        _startMove: false,
        _needStop: false,
        _backMove: false,
        //
        _resultItem: null,        // 结果索引 从1开始
        _result: null,
        _rtype:1,
        _items: [],
        _canClick:false,
        //
        _itemsHeight: 0,
    },

    onLoad() {

        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, this);
    },

    update(dt) {
        if (this._startMove) {
            if (!this._needStop) {
                this.speed += this.speedOffset;
                if (this.speed >= this.maxSpeed) {
                    this.speed = this.maxSpeed;
                }
            } else {
                this.speed -= this.speedOffset;
                if (this.speed <= this.minSpeed) {
                    this.speed = this.minSpeed;
                }
            }

            if (this.count === 0 && this._resultItem.y <= 3 * this._resultItem.height) {
                this._needStop = true;
            }

            if (this._needStop && this._resultItem.y < 0) {
                this._startMove = false;
                this._backMove = true;
            }

            for (let item of this._items) {
                if (item.y <= this._bottomPosY) {
                    item.y += this._itemsHeight;
                    if (item === this._resultItem) {
                        this.count--;
                        if (this.count <= 0) {
                            this.count = 0;
                        }
                    }
                }

                item.y -= this.speed;
            }
        }

        if (this._backMove) {
            for (let item of this._items) {
                item.y += this.minSpeed;
            }

            if (this._resultItem.y > -1 && this._resultItem.y < 1) {
                this._backMove = false;
                this.exitWheelGame();
            }
        }
    },

    onSendSeq:function(idx){
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.gameid = cc.vv.gameData.getGameId();
        req.data = {
            rtype:this._rtype,
        };
        cc.vv.NetManager.send(req,true);
    },

    onRcvSubGameAction(msg) {
        cc.log(msg)

        if (msg.code === 200 && msg.data && msg.data.rtype === this._rtype) {

            this._result = msg.data;

            this._resultItem = this._items[this._result.wheelId - 1];

            this._startMove = true;

            cc.vv.gameData.setFreeGameWheel(this._result.freeGameWheel);
        }
    },


    Init(){
        this._wheelNode = cc.find("safe_node/freeWheel", this.node);
        this._wheelNode.active = false;

        this._rollNode1 = cc.find("bg/rollNode1", this._wheelNode);
        this._rollNode2 = cc.find("bg/rollNode2", this._wheelNode);

        this._node_shou = cc.find("bg/node_shou", this._wheelNode);
        this._node_shou.active = false;

        let btn_click = cc.find("bg/btn_click", this._wheelNode);
        btn_click.off("click");
        btn_click.on("click", ()=>{
            btn_click.stopAllActions();
            this.onClickSpin();
        })

    },

    onClickSpin(){
        let self = this;
        if(!self._canClick){
            return
        }

        Global.SlotsSoundMgr.playEffect("sound_Kangaroos_click_btn");

        self._canClick = false;
        self.playShouAnim(false);
        self.onSendSeq();
    },

    enterFreeWheel(wheelData){
        return new Promise(async(success, failed)=> {
            this._wheelData = wheelData;

            this._wheelNode.active = true;
            // this._wheelNode.opacity = 0;
            // cc.tween(this._wheelNode)
            //     .to(0.5, {opacity:255})
            //     .start();
            this.reset();

            let curBet = cc.vv.gameData.GetBetIdx();
            let needBet = cc.vv.gameData.getNeedBet();

            this._rollNode1.active = curBet < needBet;
            this._rollNode2.active = curBet >= needBet;
            let parentNode = curBet < needBet ? this._rollNode1 : this._rollNode2;

            this._items = [];
            this._itemsHeight = 0;
            for (let i = 0; i < parentNode.childrenCount; i++){
                let node = cc.find("item" + (i+1), parentNode);
                if(node){
                    this._items.push(node);
                    this._itemsHeight += node.height;
                }
            }

            // 最下边的位置
            this._bottomPosY = -700;

            let getCollectInfos = cc.vv.gameData.getCollectInfos();
            let curCollectInfo = getCollectInfos[curBet-1]

            let wheel = wheelData.wheel
            for (let i = 0; i < wheel.length; i++) {
                let cfg = wheel[i];
                let node = cc.find("item" + (i+1), parentNode);
                if(cfg.type === WheelItemType.Blue){
                    cc.find("node_lbls/lbl_cnt", node).getComponent(cc.Label).string = curCollectInfo.blue.freeCnt;
                } else if(cfg.type === WheelItemType.Purple){
                    cc.find("node_lbls/lbl_cnt", node).getComponent(cc.Label).string = curCollectInfo.purple.freeCnt;
                } else if(cfg.type === WheelItemType.Red){
                    cc.find("node_lbls/lbl_cnt", node).getComponent(cc.Label).string = curCollectInfo.red.freeCnt;
                }else if (cfg.type === WheelItemType.Jackpot) {
                    cc.find("tit", node).getComponent("ImgSwitchCmp").setIndex(cfg.jackpotId-2);
                    cc.find("lbl", node).getComponent(cc.Label).string = Global.convertNumToShort(wheelData.jackpotValues[cfg.jackpotId-1], null, 0);
                }
            }

            await cc.vv.gameData.awaitTime(0.5);
            this._canClick = true;
            this.playShouAnim(true);
            let btn_click = cc.find("bg/btn_click", this._wheelNode);
            cc.vv.gameData.checkAutoPlay(btn_click, this.onClickSpin.bind(this));

            this._successCallback = success;
        })
    },

    async exitWheelGame() {

        let cfg = this._wheelData.wheel[this._result.wheelId - 1];
        let animName = "";
        let effName = "sound_Kangaroos_reward_diamond";
        if (cfg.type === WheelItemType.Jackpot) { //
            animName = "item_zs_win_jp";
            effName = "sound_Kangaroos_reward_jackpot";
        } else if(cfg.type === WheelItemType.Blue){
            animName = "item_zs_win_blue";
        } else if(cfg.type === WheelItemType.Purple){
            animName = "item_zs_win_pruple";
        } else if(cfg.type === WheelItemType.Red){
            animName = "item_zs_win_red";
        } else if(cfg.type === WheelItemType.FreeGame){ // 单纯的免费游戏
            animName = "item_zs_win_normal";
        }
        this._resultItem.getComponent(cc.Animation).play(animName);
        Global.SlotsSoundMgr.playEffect(effName);

        await cc.vv.gameData.awaitTime(2);

        // cc.tween(this._wheelNode)
        //     .to(0.5, {opacity:0})
        //     .call(()=>{
                this._wheelNode.active = false;
                if (this._successCallback) {
                    this._successCallback();
                }
            // })
            // .start()

    },

    playShouAnim(bPlay){
        let spr = cc.find("tip_shou", this._node_shou);
        if(bPlay){
            this._node_shou.active = true;

            cc.tween(spr)
                .repeatForever(
                    cc.tween()
                        .call(()=>{
                            spr.setScale(1);
                            spr.setPosition(cc.v2(0,-20));
                        })
                        .to(0.3, {opacity:255})
                        .to(0.8, {position:cc.v2(0,160)})
                        .call(()=>{
                            spr.setScale(-1);
                            spr.setPosition(cc.v2(0,180));
                        })
                        .to(0.8, {position:cc.v2(0,0)})
                        .call(()=>{
                            spr.setScale(1);
                            spr.setPosition(cc.v2(0,-20));
                        })
                        .to(0.8, {position:cc.v2(0,160)})
                        .call(()=>{
                            spr.setScale(-1);
                            spr.setPosition(cc.v2(0,180));
                        })
                        .to(0.8, {position:cc.v2(0,0)})
                        .to(0.3, {opacity:0})
                        .delay(3)

                )
                .start()
            
        } else {
            this._node_shou.active = false;
            spr.stopAllActions()
        }
    },

    reset() {
        this._startMove = false;
        this.speed = 10;
        this._needStop = false;
        this.count = 2;
        this._backMove = false;
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, false, this);
    },

    awaitTime(dt) {
        return new Promise((success, failed) => {
            this.scheduleOnce(() => {
                success()
            }, dt);
        });
    },
});