
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start() {

    },

    Init() {
        this._node_sm = cc.find("node_shuoming", this.node);
        this._node_zsCnt = cc.find("node_zsCnt", this.node);
        this._node_freeCnt = cc.find("node_freeCnt", this.node);

        this._node_diamond = cc.find("Canvas/safe_node/node_diamond");


        this._super();

        this.showShuomingSpr();
        this.showZhuanshiCnt();
    },

    RegisterEvent: function () {
        this._super();

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, this.onEventTotalbetUpdated, this)// 押注额改变
    },

    //断线重连的显示
    async ReconnectShow() {
        this._topScript.SetBackLobby(false);
        this._bottomScript.ShowBtnsByState("moveing_1");

        Global.SlotsSoundMgr.playEffect("music_Kangaroos_enter");

        let freeGameWheel = cc.vv.gameData.getFreeGameWheel();
        if (freeGameWheel) {  // 转盘
            await this.triFreeWheelGame(true);
        }
        else if (cc.vv.gameData.GetTotalFree() > 0) {
            this.ShowGameview(true);
        }
        else {
            this.ShowGameview(false);
        }

        this._topScript.StopMove()
        this._bottomScript.CanDoNextRound();
    },

    StartMove() {
        this._super();
        Global.SlotsSoundMgr.playNormalBgm();

        if (this._isFreeGame) {
            this.showFreeCnt()
        }
    },

    getRandomVal() {
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(1, cfg.randomSymbols.length)
        return cfg.randomSymbols[randIdx - 1]
    },

    SetSlotsResult: function (cards) {
        let cnts = [];
        let idxs = [];
        let watermarkInfo = this._gameInfo.watermarkInfo;
        if (watermarkInfo) {
            cnts = watermarkInfo.cnts;
            idxs = watermarkInfo.idxs;
        }
        cnts = Array.isArray(cnts) ? cnts : (cnts && typeof(cnts) === "object") ? Object.values(cnts) : []
        idxs = Array.isArray(idxs) ? idxs : (idxs && typeof(idxs) === "object") ? Object.values(idxs) : []
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []
        for (let i = 0; i < cards.length; i++) {
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if (cards[i] == 20) {
                cards[i] = this.getRandomVal()
            }
            if (this._cfg.symbol[cards[i]]) {
                let res = {}
                res.sid = cards[i] //符号id
                res.data = {};
                if (idxs.includes(i + 1)) { // By JerryWong
                    res.data.cnt = cnts[idxs.indexOf(i + 1)]
                }
                if (this._gameInfo.currDiamond && this._gameInfo.currDiamond.idx == i + 1) {
                    res.data.diamond = this._gameInfo.currDiamond;
                }
                if (!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
        }
        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    OnSpinEnd() {
        this.onSpinEndAction();
    },

    async onSpinEndAction() {

        // 飞角标
        let watermarkInfo = this._gameInfo.watermarkInfo;
        if (watermarkInfo && watermarkInfo.totalCnt > 0) {
            cc.vv.gameData.getStoreScript().flyJiaobiao();
            await cc.vv.gameData.awaitTime(0.5)
        }

        // 加钻石
        if (this._gameInfo.currDiamond) {
            await this.addDiamond();
        }

        // 显示中奖路线
        this.ShowWinTrace()
        // 显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        let updateBalance = true;
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.getFreeWinCoin()
            this.showFreeWin(false, nTotal)
            updateBalance = false;
        }
        await new Promise((success, failed) => {
            this.ShowBottomWin(nWin, nTotal, updateBalance, success)
        });

        // 触发免费转盘
        let freeGameWheel = this._gameInfo.freeGameWheel;
        if (freeGameWheel) {
            await this.triFreeWheelGame(false);
        }

        // 再次触发免费
        let freeInfo = this._gameInfo.freeResult.freeInfo;
        if (freeInfo && freeInfo.freeCnt > 0 && this._gameInfo.allFreeCnt != this._gameInfo.freeCnt) {
            await this.triFreeGameAgain();
        }

        if (this._gameInfo.freeCnt == 0 && this._gameInfo.allFreeCnt > 0) {
            await this.endFreeGame();
        }



        this.CanDoNextRound();
    },

    addDiamond() {
        return new Promise(async (success, failed) => {

            let idx = this._gameInfo.currDiamond.idx;
            let type = this._gameInfo.currDiamond.type;     // 1-蓝色 2-紫色 3-红色

            let nameList = ["diamond_blue", "diamond_purple", "diamond_red"];
            let animList = ["zs_stop_b", "zs_stop_p", "zs_stop_r"];
            let endNodeList = ["pos_b", "pos_p", "pos_r"];

            let symbol = this.GetSymbolByIdx(idx);
            symbol.showDiamond()
            let s_pos = this._node_diamond.convertToNodeSpaceAR(symbol.node.convertToWorldSpaceAR(cc.v2(0, 0)));
            let e_node = cc.find(endNodeList[type - 1], this._node_zsCnt);
            let e_pos = this._node_diamond.convertToNodeSpaceAR(e_node.convertToWorldSpaceAR(cc.v2(0, 0)));

            let fab_name = nameList[type - 1];
            let node_zs = cc.instantiate(cc.vv.gameData.GetPrefabByName(fab_name));
            node_zs.parent = this._node_diamond;
            node_zs.active = true;
            node_zs.position = s_pos;

            Global.SlotsSoundMgr.playEffect("sound_Kangaroos_diamond_1");
            let spN = node_zs.getChildByName("spine").getComponent(sp.Skeleton);
            spN.setAnimation(0, "animation1", false);
            spN.addAnimation(0, "animation", true);
            await cc.vv.gameData.awaitTime(1);




            // node_zs.getComponent(cc.Animation).play(animList[type-1]);
            // node_zs.getComponent(cc.Animation).off("stop");
            // node_zs.getComponent(cc.Animation).on("stop", ()=>{
            cc.tween(node_zs)
                .to(0.5, { position: e_pos })
                // .call(()=>{
                // })
                .start()
            // }, this);
            await cc.vv.gameData.awaitTime(0.5);
            this.showZhuanshiCnt();
            let entry = spN.setAnimation(0, "animation2", false);
            spN.setTrackCompleteListener(entry, () => {
                spN.setTrackCompleteListener(entry, null);
                node_zs.destroy();
            })
            Global.SlotsSoundMgr.playEffect("sound_Kangaroos_diamond_2");
            success();

        });
    },

    triFreeGameAgain() {
        return new Promise(async (success, failed) => {
            let freeInfo = this._gameInfo.freeResult.freeInfo;
            for (let i = 0; i < freeInfo.scatterIdx.length; i++) {
                let symbol = this.GetSymbolByIdx(freeInfo.scatterIdx[i]);
                if (symbol) {
                    symbol.playTriggerAnimation();
                }
            }
            Global.SlotsSoundMgr.playEffect("music_Kangaroos_trriger_scatter");
            await cc.vv.gameData.awaitTime(2);

            await cc.vv.gameData.getPopupScript().playTriFreeAgainAnim(freeInfo.freeCnt);

            success();
        });
    },

    triFreeWheelGame(bReconnect) {
        return new Promise(async (success, failed) => {
            let result = cc.vv.gameData.getFreeGameWheel();
            if (!bReconnect) {
                for (let i = 0; i < result.scatterIdx.length; i++) {
                    let symbol = this.GetSymbolByIdx(result.scatterIdx[i]);
                    if (symbol) {
                        symbol.playTriggerAnimation();
                    }
                }
                Global.SlotsSoundMgr.playEffect("music_Kangaroos_trriger_scatter");
                await cc.vv.gameData.awaitTime(2);

                cc.vv.gameData.getPopupScript().playQpAnim();

                await cc.vv.gameData.awaitTime(2);
            }

            await cc.vv.gameData.getFreeWheelScript().enterFreeWheel(result);

            result = cc.vv.gameData.getFreeGameWheel();
            if (result.jackpot) {
                await cc.vv.gameData.getPopupScript().playWinJpAnim(result.jackpot.value, result.jackpot.id);
                cc.vv.gameData.AddCoin(result.jackpot.value);
                this._topScript.ShowCoinByRoll()
            } else if (result.freeInfo) {
                let freeCnt = result.freeInfo.freeCnt;
                let mult = result.freeInfo.mult;
                cc.vv.gameData.SetFreeTime(freeCnt);
                cc.vv.gameData.SetTotalFree(freeCnt);
                cc.vv.gameData.setFreeMult(mult);

                this.Backup();
                this.ShowGameview(true);
                cc.vv.gameData.getPopupScript().playQpAnim();

                await cc.vv.gameData.awaitTime(2);

                await cc.vv.gameData.getPopupScript().playTriFreeAnim(freeCnt, mult);

                Global.SlotsSoundMgr.playBgm("music_Kangaroos_freespin_bg");
            }
            success();
        });
    },

    endFreeGame() {
        return new Promise(async (success, failed) => {
            Global.SlotsSoundMgr.stopBgm();

            let winCoin = cc.vv.gameData.getFreeWinCoin();
            await cc.vv.gameData.getPopupScript().playEndFreeAnim(winCoin, this._gameInfo.allFreeCnt);
            cc.vv.gameData.getPopupScript().playQpAnim();

            await cc.vv.gameData.awaitTime(1);
            this.showZhuanshiCnt();
            this.ShowGameview(false);
            this.Resume();

            await cc.vv.gameData.awaitTime(2);
            await new Promise((sucess, failed) => {
                this.ShowBottomWin(winCoin, winCoin, true, sucess)
            });

            success();
        });
    },

    showZhuanshiCnt() {
        let infos = cc.vv.gameData.getCollectInfos();
        let curBet = cc.vv.gameData.GetBetIdx();

        let curInfo = infos[curBet - 1];

        cc.find("lbl_4", this._node_zsCnt).getComponent(cc.Label).string = curInfo.red.freeCnt;
        cc.find("lbl_3", this._node_zsCnt).getComponent(cc.Label).string = curInfo.purple.freeCnt;
        cc.find("lbl_2", this._node_zsCnt).getComponent(cc.Label).string = curInfo.blue.freeCnt;
    },

    showShuomingSpr() {
        let curBet = cc.vv.gameData.GetBetIdx();
        let needBet = cc.vv.gameData.getNeedBet();

        cc.find("zi1", this._node_sm).active = curBet >= needBet;
        cc.find("zi2", this._node_sm).active = curBet < needBet;
        cc.find("par_shuoming", this._node_sm).active = false;
    },

    // 押注额改变
    onEventTotalbetUpdated() {
        let curBet = cc.vv.gameData.GetBetIdx();
        let needBet = cc.vv.gameData.getNeedBet();

        let zi1 = cc.find("zi1", this._node_sm);
        let zi2 = cc.find("zi2", this._node_sm);
        let par = cc.find("par_shuoming", this._node_sm);
        if (curBet >= needBet && zi2.active) {
            Global.SlotsSoundMgr.playEffect("");
            par.active = true;
            par.getComponent(cc.ParticleSystem).resetSystem();
            zi1.active = true;
            zi2.active = false;
            cc.tween(zi1).to(0.3, { scale: 1.1 }).to(0.2, { scale: 1 }).start();
        } else if (curBet < needBet && zi1.active) {
            Global.SlotsSoundMgr.playEffect("");
            par.active = true;
            par.getComponent(cc.ParticleSystem).resetSystem();
            zi1.active = false;
            zi2.active = true;
            cc.tween(zi2).to(0.3, { scale: 1.1 }).to(0.2, { scale: 1 }).start();
        }

        this.showZhuanshiCnt();
    },

    showFreeCnt() {
        let total = cc.vv.gameData.GetTotalFree();
        let rest = cc.vv.gameData.GetFreeTime();

        cc.find("zi/curCnt", this._node_freeCnt).getComponent(cc.Label).string = total - rest;
        cc.find("zi/totalCnt", this._node_freeCnt).getComponent(cc.Label).string = total;
    },

    showFreeWin(init, winCoin) {
        let lbl = cc.find("lbl_win", this._node_freeCnt);
        if (init) {
            lbl.getComponent(cc.Label).string = Global.FormatNumToComma(winCoin)
        } else {
            let s_num = Global.FormatCommaNumToNum(lbl.getComponent(cc.Label).string);
            Global.doRoallNumEff(lbl, s_num, winCoin, 1, null, null, 0, true);
        }
    },

    showFreeMult(mult) {
        let spr = cc.find("spr_mult", this._node_freeCnt);
        let zi = cc.find("zi", this._node_freeCnt);
        if (mult >= 2) {
            spr.active = true;
            zi.position = cc.v2(30, spr.y);
            spr.getComponent("ImgSwitchCmp").setIndex(mult - 2);
        } else {
            spr.active = false;
            zi.position = cc.v2(0, spr.y);
        }
    },

    ShowGameview: function (bFree) {
        this._super(bFree);

        cc.find("Canvas/safe_node/kangaroo").active = !bFree;
        this._node_zsCnt.active = !bFree;
        this._node_sm.active = !bFree;
        this._node_freeCnt.active = bFree;

        this._isFreeGame = bFree;
        cc.vv.gameData.setIsFreeGame(bFree);

        if (bFree) {
            this.showFreeCnt();
            this.showFreeWin(true, cc.vv.gameData.getFreeWinCoin());
            this.showFreeMult(cc.vv.gameData.getFreeMult())
        }
    },


    // update (dt) {},
});
