
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    // 清除所有状态
    // ClearState(){
    //     this.showPaw();
    //     this.setAnimationToTop(false)
    //     this.ShowKuang(false)
    //     this.stopWinTweenAction()
    //     this.node.zIndex = 50 - this._symbolIdx  + this._reelIdx*10;
    // },

    //显示symbole
    //id:物品id
    //data:额外传递的数据
    ShowById:function(id,data){
        this._super(id, data)


        this.showJiaobiao();
        this.showDiamond();

        if(this._isResume){
            this._isResume = false;
        } else {
            if(data){
                if(data.cnt){
                    this.showJiaobiao(data.cnt);
                }

                if(data.diamond){
                    this.showDiamond(data.diamond);
                }
            }
        }
    },

    showJiaobiao(val){
        let node_jiaobiao = cc.find("jiaobiao", this.node);
        if(val){
            node_jiaobiao.active = true;
            cc.find("lbl", node_jiaobiao).getComponent(cc.Label).string = val;
        } else {
            node_jiaobiao.active = false;
        }
    },

    getJiaobiao(){
        return cc.find("jiaobiao", this.node)
    },


    showDiamond(data){
        cc.find("zs_blue", this.node).active = data && data.type == 1;
        cc.find("zs_purple", this.node).active = data && data.type == 2;
        cc.find("zs_red", this.node).active = data && data.type == 3;
    },

    //恢复到保存的状态
    Resume(backup) {
        this._isResume = true;

        this.stopWinTweenAction()
        this._super(backup);
    },

    //赢钱动画
    playWinAnimation(){
        if(this._showNode){
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node){
            this._state = "win";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].win_ani && cfg.symbol[id].win_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].win_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){

                    let animName = cfg.symbol[id].win_ani.name;
                    if(id == 1){
                        let mult = cc.vv.gameData.getWildMult();
                        if(mult == 2){
                            animName = cfg.symbol[id].win_ani.name2;
                        } else if(mult == 3){
                            animName = cfg.symbol[id].win_ani.name3;
                        }
                    }

                    nodeSp.setAnimation(0,animName,true)
                }
            }
        }
        else{
            //如果没有中奖动画，先显示出来
            //TODO：后续补充一个没有spin动画的显示效果
            this._showNode.active = true
            this.playWinTweenAction()
        }
    },



    // update (dt) {},
});
