
// 1-锁 2-可点击 3-免费的 4-不可点击 5-钱 6-2X
let itemType = {
    lock     : 1,
    canClick : 2,
    freeClick: 3,
    unClick  : 4,
    coin     : 5,
    again    : 6,
};

cc.Class({
    extends: cc.Component,

    properties: {
        _rtype:2,

        _itemList:[],
        _repick:false, // 当前为免费(开到again的后一把)

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this._btn_entrance = cc.find("safe_node/slots/btn_entrance", this.node);
        this._btn_entrance.off("click");
        Global.btnClickEvent(this._btn_entrance, this.onClickEntranceBtn, this);
        this._fly_jiaobiao = cc.find("par_fly", this._btn_entrance);
        this._fly_jiaobiao.active = false;

        this._node_store = cc.find("safe_node/node_store", this.node);
        this._node_store.active = false;
        this._layout = cc.find("layout", this._node_store);

        this._btn_close = cc.find("layout/btn_close", this._node_store);
        Global.btnClickEvent(this._btn_close, this.onClickCloseBtn, this);

        this._node_items = cc.find("layout/node_items", this._node_store);
        for (let i = 1; i <= 9; i++){
            let item = cc.find("item"+i, this._node_items);
            item.off("click");
            Global.btnClickEvent(item, this.onClickItem, this);

            this._itemList[i] = {node:item,type:1,data:null};
        }

        this._par_sj = cc.find("layout/par_sj", this._node_store);
        this._par_sj.active = false;
        this._box_tip = cc.find("layout/box_tip", this._node_store);
        this._box_tip.active = false;

        let btn_left = cc.find("layout/btn_left", this._node_store);
        Global.btnClickEvent(btn_left, this.clickLeftBtn, this);
        let btn_right = cc.find("layout/btn_right", this._node_store);
        Global.btnClickEvent(btn_right, this.clickRightBtn, this);

        this.updateCurMoney();

    },


    onEnable(){
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, this);
    },

    onDisable(){
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, false, this);
    },



    // 点入口图标
    onClickEntranceBtn(){
        if (!cc.vv.gameData.GetBottomScript().GetSpinBtnState()) return;
        if (cc.vv.gameData.GetAutoModelTime() > 0) return;
        if (cc.vv.gameData.isFreeGame()) return;

        Global.SlotsSoundMgr.playEffect("");

        this._btn_entrance.getComponent(cc.Button).interactable = false;
        this.openStorePage();
    },


    // 打开商店页面
    openStorePage(){
        return new Promise(async(success, failed)=> {
            Global.SlotsSoundMgr.playBgm("sound_Kangaroos_shop_bgm");
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");

            this._node_store.active = true;
            this._layout.setScale(0);
            cc.tween(this._layout).to(0.5, {scale:1}, {easing:"backOut"}).start();

            this._storeInfo = cc.vv.gameData.getStoreInfo();
            this._curPage = this._storeInfo.unlockPage;

            this._repick = this._storeInfo.repick;

            this.updateCurMoney();
            this.showTitleSpr();
            this.showAllItems();
            this.showPageFooter();

            await cc.vv.gameData.awaitTime(0.5);
            this._canClickItem = true;

            success();
        })
    },

    // 关闭商店页面
    async closeStorePage(){
        return new Promise(async(success, failed)=>{
            Global.SlotsSoundMgr.stopBgm();

            // cc.vv.gameData.GetBottomScript().ShowBtnsByState("idle");

            cc.tween(this._layout).to(0.5,{opacity:0,scale:0}).start();

            await cc.vv.gameData.awaitTime(0.5);
            this._btn_entrance.getComponent(cc.Button).interactable = true;
            this._node_store.active = false;
            this._layout.opacity = 255;

            success();
        })
    },

    onClickCloseBtn(){
        if(!this._canClickItem){
            return
        }

        Global.SlotsSoundMgr.playEffect("sound_Kangaroos_shop_btnclose");
        this.closeStorePage();
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("idle");

    },

    // 飞角标
    async flyJiaobiao(){
        let watermarkInfo = cc.vv.gameData.getWatermarkInfo();
        let cnts = watermarkInfo.cnts;
        let idxs = watermarkInfo.idxs;
        let totalCnt = watermarkInfo.totalCnt;

        Global.SlotsSoundMgr.playEffect("sound_Kangaroos_shop_collectcoins_1");

        let self = this;
        let spr = cc.find("spr", this._btn_entrance);
        for (let i = 0; i < idxs.length; i++){
            let jiaobiao = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(idxs[i]).getJiaobiao();
            jiaobiao.active = false;
            // cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(idxs[i]).showJiaobiao();

            let flyNode = cc.instantiate(this._fly_jiaobiao);
            flyNode.active = true;
            flyNode.parent = this._fly_jiaobiao.parent;
            flyNode.position = flyNode.parent.convertToNodeSpaceAR(jiaobiao.convertToWorldSpaceAR(cc.v2(0,0)));
            let lbl = cc.find("jiaobiao/lbl",flyNode);
            lbl.getComponent(cc.Label).string = cnts[i];

            let endPos = flyNode.parent.convertToNodeSpaceAR(spr.convertToWorldSpaceAR(cc.v2(0,0)));
            cc.tween(flyNode)
                .to(0.3, {scale:0.8})
                .to(0.2,{scale:1})
                .parallel(
                    cc.tween().to(0.5,{position:endPos, opacity:0}),
                    cc.tween().call(()=>{
                        cc.tween(lbl).to(0.5,{opacity:0}).start();
                        // self.updateCurMoney(true);
                    })
                )
                .call(()=>{
                    flyNode.destroy();
                    cc.tween(spr).to(0.3,{scale:1.3}).to(0.2,{scale:1}).start()
                })
                .start()
        }

        await cc.vv.gameData.awaitTime(0.5);
        Global.SlotsSoundMgr.playEffect("sound_Kangaroos_shop_collectcoins_2");
        this.updateCurMoney(totalCnt)
    },

    // 更新当前剩余钱数
    updateCurMoney(addCnt){
        this._storeInfo = cc.vv.gameData.getStoreInfo();

        let lbl_money = cc.find("lbl", this._btn_entrance);
        if(addCnt){
            let curCnt = Global.FormatCommaNumToNum(lbl_money.getComponent(cc.Label).string);
            Global.doRoallNumEff(lbl_money,curCnt,this._storeInfo.watermarkCnt, 0.5,null,null,0,true);
        } else {
            lbl_money.getComponent(cc.Label).string = Global.FormatNumToComma(this._storeInfo.watermarkCnt);
        }


        let lbl = cc.find("layout/money_bg/lbl", this._node_store);
        lbl.getComponent(cc.Label).string = Global.FormatNumToComma(this._storeInfo.watermarkCnt);
    },

    // 标题
    showTitleSpr(bPlay){
        let spr_content = cc.find("layout/spr_content", this._node_store);

        if(bPlay){
            cc.tween(spr_content)
                .to(0.3, {opacity:0})
                .call(()=>{
                    spr_content.getComponent("ImgSwitchCmp").setIndex(this._curPage-1);
                })
                .to(0.3, {opacity:255})
                .start();
        } else {
            spr_content.getComponent("ImgSwitchCmp").setIndex(this._curPage-1);
        }
    },

    // 所有格子
    showAllItems(){
        let pageData = this._storeInfo.unlockItems[this._curPage - 1];
        let pagePrice = this._storeInfo.pageDetails[this._curPage - 1].price;

        for(let i = 1; i <= 9; i++){
            let item = this._itemList[i].node;

            let type = this._itemList[i].type;
            let data = this._itemList[i].data;
            if(this._curPage <= this._storeInfo.unlockPage){  // 页面解锁
                let itemData = this.getItemData(i, pageData);
                if(itemData){   // 已经打开
                    if(itemData.type == 1){ // 金币
                        type = itemType.coin;
                        data = itemData.coin;
                    } else if(itemData.type == 2){ // 2X
                        type = itemType.again;
                    }
                }
                else {
                    if(this._curPage == this._storeInfo.unlockPage && this._repick){ // 前一格为again
                        type = itemType.freeClick;
                        data = pagePrice;
                    } else if(pagePrice <= this._storeInfo.watermarkCnt){ // 钱足够
                        type = itemType.canClick;
                        data = pagePrice;
                    } else {    // 钱不够
                        type = itemType.unClick;
                        data = pagePrice;
                    }
                }
            }
            else {  // 箱子锁住
                type = itemType.lock;
                data = pagePrice;
            }
            this.setItemState(item, type, data);
            this._itemList[i].type = type;
            this._itemList[i].data = data;
        }
    },

    // 获取单个房子的数据
    getItemData(idx, pageData){
        for (let i = 0; i < pageData.length; i++){
            if(idx == pageData[i].idx){
                return pageData[i]
            }
        }
        return null
    },

    // 设置单个格子的状态  type: 1-锁 2-可点击 3-免费的 4-不可点击 5-钱 6-2X
    setItemState(item, type, data){
        let spr_fangge = cc.find("spr_fangge", item);
        let spr_fanggedi = cc.find("spr_fanggedi", item);
        let spr_shade = cc.find("spr_shade", item);
        let spr_again = cc.find("spr_pickagain", item);
        let spr_suo = cc.find("spr_suo", item);
        let money_bg = cc.find("money_bg", item);
        let lbl = cc.find("lbl", item);

        spr_fangge.active = type === itemType.lock || type === itemType.canClick || type === itemType.unClick || type === itemType.freeClick;
        if(type === itemType.canClick ||  type === itemType.freeClick){
            spr_fangge.getComponent(cc.Animation).play("box_sg");
        } else {
            spr_fangge.getComponent(cc.Animation).stop();
        }
        spr_fanggedi.active = type === itemType.coin || type === itemType.again;
        spr_shade.active = type === itemType.lock || type === itemType.unClick;
        spr_again.active = type === itemType.again;
        if(spr_again.active && this._repick){
            cc.tween(spr_again).repeatForever(cc.tween().to(0.3,{scale:1.2}).to(0.3,{scale:1})).start()
        }else {
            spr_again.stopAllActions();
        }
        spr_suo.active = type === itemType.lock;
        money_bg.active = type === itemType.canClick || type === itemType.unClick || type === itemType.lock;
        if(money_bg.active){
            cc.find("lbl", money_bg).getComponent(cc.Label).string = Global.FormatNumToComma(data);
        }
        lbl.active = type === itemType.coin;
        if(lbl){
            lbl.getComponent(cc.Label).string = Global.formatNumShort(data,0);
        }
    },

    getAgainItem(){
        for (let i = 1; i <= 9; i++){
            if(this._itemList[i].type == itemType.again){
                return this._itemList[i].node
            }
        }
        return null;
    },

    // 点格子
    onClickItem(event){
        if(!this._canClickItem){
            return
        }

        let idx =  Number(event.node.name.substring("item".length));
        let curType = this._itemList[idx].type;
        if(curType === itemType.lock || curType === itemType.unClick){
            this.playBoxTipAnim(event.node);
        } else if(curType === itemType.canClick || curType === itemType.freeClick){
            Global.SlotsSoundMgr.playEffect("sound_Kangaroos_shop_buy_start");

            this._canClickItem = false;
            this.onSendSeq(idx);
        }
    },

    onSendSeq:function(idx){
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.gameid = cc.vv.gameData.getGameId()
        req.data = {
            rtype:this._rtype,
            pageId:this._curPage,
            choiceId:idx,
        }
        cc.vv.NetManager.send(req,true);
    },

    onRcvSubGameAction(msg){
        let data  = msg.data;
        if(msg.code === 200 && data && data.rtype == this._rtype){
            this.showClickResult(data);
        }
    },

    // 点击结果
    async showClickResult(data){
        this._storeInfo = data.storeInfo;
        cc.vv.gameData.setStoreInfo(this._storeInfo);
        this.updateCurMoney();

        let result = data.result;
        let idx = data.choiceId;

        await this.setItemResult(idx, result);

        if(!this._repick && this._storeInfo.pageDetails[this._curPage-1].price > this._storeInfo.watermarkCnt){  // 钱不够
            for (let i = 1; i <= 9; i++){
                if(this._itemList[i].type === itemType.canClick){
                    this._itemList[i].type = itemType.unClick;
                    this.setItemState(this._itemList[i].node, itemType.unClick, this._itemList[i].data)
                }
            }
        }

        if(result.pageReward){
            await cc.vv.gameData.awaitTime(1);
            await this.closeStorePage();

            if(result.pageReward){  // 集满
                let freeCnt = result.pageReward.freeCnt;

                cc.vv.gameData.SetTotalFree(freeCnt);
                cc.vv.gameData.SetFreeTime(freeCnt);

                cc.log("this._curPage:",this._curPage );
                await cc.vv.gameData.getPopupScript().playTriSuperFreeAnim(freeCnt, this._curPage);
                cc.vv.gameData.getPopupScript().playQpAnim();
                await cc.vv.gameData.awaitTime(1);
                cc.vv.gameData.GetSlotsScript().ShowGameview(true);
                await cc.vv.gameData.awaitTime(1);
                cc.vv.gameData.GetSlotsScript().CanDoNextRound();
            }
        } else {
            // 设置可以再次点击
            this._canClickItem = true;
        }
    },

    // 格子打开后动画
    setItemResult(idx, data){
        return new Promise(async(success, failed)=>{
            Global.SlotsSoundMgr.playEffect("sound_Kangaroos_shop_buy_loop");

            let item = this._itemList[idx].node;

            let spr_fangge = cc.find("spr_fangge", item);
            let spr_fanggedi = cc.find("spr_fanggedi", item);
            let spr_shade = cc.find("spr_shade", item);
            let spr_again = cc.find("spr_pickagain", item);
            let spr_suo = cc.find("spr_suo", item);
            let money_bg = cc.find("money_bg", item);
            let lbl = cc.find("lbl", item);

            cc.tween(money_bg)
                .to(0.3, {opacity:0})
                .call(()=>{
                    money_bg.active = false;
                    money_bg.opacity = 255;
                })
                .start();
            await cc.vv.gameData.awaitTime(0.3);
            cc.tween(spr_fangge)
                .to(0.2, {scaleX:-1})
                .to(0.2, {scaleX:1})
                .to(0.2, {scaleX:-1})
                .to(0.2, {scaleX:1})
                .to(0.2, {scaleX:-0.5, scaleY:0.5})
                .to(0.2, {scaleX:0, scaleY:0})
                .call(()=>{
                    spr_fangge.active = false;
                    spr_fangge.setScale(1)
                })
                .start();

            await cc.vv.gameData.awaitTime(1.2);

            spr_fanggedi.active = true;
            spr_fanggedi.setScale(0);
            cc.tween(spr_fanggedi).to(0.5, {scale:1}, {easing:"backOut"}).start();

            if(data.coin > 0){
                lbl.active = true;
                lbl.getComponent(cc.Label).string = Global.formatNumShort(data.coin/(this._repick?2:1),0);
                lbl.setScale(0);
                cc.tween(lbl).to(0.5, {scale:1}, {easing:"backOut"}).start();

                if(this._repick){
                    await cc.vv.gameData.awaitTime(0.5);
                    let again_item = this.getAgainItem();
                    this._par_sj.active = true;
                    this._par_sj.position = this._par_sj.parent.convertToNodeSpaceAR(again_item.convertToWorldSpaceAR(cc.v2(0,0)));
                    let endPos = this._par_sj.parent.convertToNodeSpaceAR(item.convertToWorldSpaceAR(cc.v2(0,0)));
                    cc.tween(this._par_sj).to(0.5, {position:endPos}).start();
                    await cc.vv.gameData.awaitTime(0.5);
                    this._par_sj.active = false;
                    lbl.getComponent(cc.Label).string = Global.formatNumShort(data.coin,0);
                }

                let rollData={lblCoin:cc.find(Global.INGAME_COIN_LABEL_NODE_PATH), addCoin:data.coin};
                Global.FlyCoin(lbl, cc.find(Global.INGAME_COIN_NODE_PATH), null, rollData);

                this._itemList[idx].type = itemType.coin;

                if(this._repick){
                    this._repick = false;

                    for (let i = 1; i <= 9; i++){
                        if(this._itemList[i].type === itemType.freeClick){
                            this._itemList[i].type = itemType.canClick;
                            this.setItemState(this._itemList[i].node, itemType.canClick, this._itemList[i].data)
                        } else if(this._itemList[i].type === itemType.again){
                            this.setItemState(this._itemList[i].node, this._itemList[i].type, this._itemList[i].data)
                        }
                    }

                }
            } else if(data.mult > 1){
                spr_again.active = true;
                cc.tween(spr_again).repeatForever(cc.tween().to(0.3,{scale:1.2}).to(0.3,{scale:1})).start()
                lbl.setScale(0);
                cc.tween(lbl).to(0.5, {scale:1}, {easing:"backOut"}).start();

                this._itemList[idx].type = itemType.again;

                this._repick = true;
                for (let i = 1; i <= 9; i++){
                    if(this._itemList[i].type === itemType.canClick){
                        this._itemList[i].type = itemType.freeClick;
                        this.setItemState(this._itemList[i].node, itemType.freeClick, this._itemList[i].data)
                    }
                }
            }
            await cc.vv.gameData.awaitTime(0.5);
            Global.SlotsSoundMgr.playEffect("sound_Kangaroos_shop_buy_over");

            success();
        })

    },


    // 格子提示动画
    playBoxTipAnim(node){
        this._box_tip.stopAllActions();
        if(this._box_tip.active){
            this._box_tip.runAction(cc.sequence(
                cc.scaleTo(this._box_tip.scaleX/2,0,0),
                cc.callFunc(()=>{ this._box_tip.active = false;})
            ))
        } else {
            this._box_tip.position = this._box_tip.parent.convertToNodeSpaceAR(node.convertToWorldSpaceAR(cc.v2(0,0)));
            this._box_tip.active = true;
            this._box_tip.setScale(0);
            this._box_tip.runAction(cc.sequence(
                cc.scaleTo(0.5,1,1),
                cc.delayTime(1),
                cc.scaleTo(0.5,0,0),
                cc.callFunc(()=>{ this._box_tip.active = false;})
            ))
        }
    },

    // 当前页码
    showPageFooter(){
        for (let i = 1; i <= 5; i++){
            let choosed = cc.find(cc.js.formatStr("layout/choose_bg/choose%s/choosed", i), this._node_store);

            choosed.active = i === this._curPage;
        }
    },

    // 左翻页
    async clickLeftBtn(){
        if(!this._canClickItem){
            return
        }
        this._canClickItem = false;

        if(this._curPage<=1){
            this._curPage = 5;
        }else{
            this._curPage--;
        }

        this.refreshDataWithAction(20);
        this.showPageFooter();

        await cc.vv.gameData.awaitTime(1);
        this._canClickItem = true
    },

    // 右翻页
    async clickRightBtn(){
        if(!this._canClickItem){
            return
        }
        this._canClickItem = false;

        if(this._curPage>=5){
            this._curPage = 1;
        }else{
            this._curPage++;
        }


        this.refreshDataWithAction(-20);
        this.showPageFooter();

        await cc.vv.gameData.awaitTime(1);
        this._canClickItem = true
    },

    async refreshDataWithAction(deltaX){
        Global.SlotsSoundMgr.playEffect("sound_Kangaroos_shop_btnnextpage");

        if(deltaX != 0){
            this._node_items.stopAllActions();
            this._node_items.x = 0;
            this._node_items.runAction(cc.sequence(cc.spawn(cc.fadeTo(0.15,63),cc.moveBy(0.15,deltaX,0)),
                cc.spawn(cc.fadeTo(0.15,255),cc.moveBy(0.15,-deltaX,0))));

            this.showTitleSpr(true);
        }

        this.showAllItems();
        for(let i=1; i<=9; i++){
            let item = this._itemList[i].node;
            item.setScale(0.1);
            item.stopAllActions();
            item.runAction(cc.scaleTo(0.1*i, 1,1).easing(cc.easeBackOut()))
        }
    },

    // update (dt) {},
});
