
cc.Class({
    extends: require("LMSlots_PrizePool_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    InItPoolList(){
        this._super();

        for(let i = 0; i < this._poolList.length; i++){
            let item = this._poolList[i].node;

            item.active = false;
            item.opacity = 0;

            let moveT = 0.5;
            let delayT = 4.5;
            cc.tween(item)
                .delay(i*(moveT+delayT))
                .repeatForever(cc.tween()
                    .call(()=>{item.active = true;item.position = cc.v2(-50, 0);
                    })
                    .to(moveT, {position:cc.v2(0, 0), opacity:255})
                    .delay(delayT)
                    .to(moveT, {position:cc.v2(50, 0), opacity:0})
                    .delay(delayT*(this._poolList.length-1)+moveT)
                )
                .start();


        }
    },






});
