
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this._node_popup = cc.find("safe_node/node_popup", this.node);
        this._node_popup.active = false;

        this._node_tri_superFree = cc.find("node_tri_superFree", this._node_popup);
        this._node_tri_free = cc.find("node_tri_free", this._node_popup);
        this._node_end_free = cc.find("node_end_free", this._node_popup);
        this._node_tri_free_again = cc.find("node_tri_free_again", this._node_popup);
        this._node_win_jp = cc.find("node_win_jp", this._node_popup);
        this._node_tri_superFree.active = false;
        this._node_tri_free.active = false;
        this._node_end_free.active = false;
        this._node_tri_free_again.active = false;
        this._node_win_jp.active = false;

        this._node_qp = cc.find("safe_node/node_qp", this.node);
        this._node_qp.active = false;

    },

    playPanelAnim(bShow, p_node){
        return new Promise(async(success, failed)=> {
            let c_cnt = p_node.childrenCount;
            for (let i = 0; i < c_cnt; i++) {
                let node = p_node.children[i];
                let s_scale = node.scale;
                if(bShow){
                    node.active = true;
                    node.setScale(0);
                    cc.tween(node).delay(i * 0.1).to(0.5, {scale: s_scale}, {easing: "backOut"}).start()
                } else {
                    cc.tween(node).delay((c_cnt-i)*0.1).to(0.5,{scale:0}, {easing:"backIn"})
                        .call(()=>{node.active = false;node.setScale(s_scale);}).start()
                }
            }
            await cc.vv.gameData.awaitTime(c_cnt * 0.1 + 0.5);

            success();
        });
    },

    // 收集满触发免费
    playTriSuperFreeAnim(freeCnt, curPage){
        return new Promise(async(success, failed)=>{
            Global.SlotsSoundMgr.playEffect("sound_Kangaroos_shop_super_freespin");
            this._node_popup.active = true;
            this._node_tri_superFree.active = true;

            cc.find("spr_up", this._node_tri_superFree).getComponent("ImgSwitchCmp").setIndex(curPage-1);
            cc.find("spr_down", this._node_tri_superFree).getComponent("ImgSwitchCmp").setIndex(curPage-1);

            let btn = cc.find("btn", this._node_tri_superFree);
            btn.off("click");
            btn.getComponent(cc.Button).interactable = true;

            await this.playPanelAnim(true, this._node_tri_superFree);

            let self = this;
            let clickFunc = async()=>{
                Global.SlotsSoundMgr.playEffect("sound_Kangaroos_click_btn");
                btn.getComponent(cc.Button).interactable = false;

                await self.playPanelAnim(false, self._node_tri_superFree);

                self._node_popup.active = false;
                self._node_tri_superFree.active = false;
                success();
            };
            cc.vv.gameData.checkAutoPlay(btn, clickFunc);
            btn.on("click", async()=>{
                btn.stopAllActions();
                clickFunc()
            });
        })
    },

    // 触发免费
    playTriFreeAnim(freecnt, mult){
        return new Promise(async(success, failed)=>{
            Global.SlotsSoundMgr.playEffect("sound_Kangaroos_pop_window");

            this._node_popup.active = true;
            this._node_tri_free.active = true;

            cc.find("spr_kuang/lbl", this._node_tri_free).getComponent(cc.Label).string = freecnt;
            cc.find("allpays", this._node_tri_free).opacity = mult>=2 ? 255 : 0;

            if(mult >= 2){
                cc.find("allpays/spr", this._node_tri_free).getComponent("ImgSwitchCmp").setIndex(mult-2);
            }

            let btn = cc.find("btn", this._node_tri_free);
            btn.off("click");
            btn.getComponent(cc.Button).interactable = true;

            await this.playPanelAnim(true, this._node_tri_free);

            let self = this;
            let clickFunc = async()=>{
                Global.SlotsSoundMgr.playEffect("sound_Kangaroos_click_btn");
                btn.getComponent(cc.Button).interactable = false;

                await self.playPanelAnim(false, self._node_tri_free);

                self._node_popup.active = false;
                self._node_tri_free.active = false;
                success();
            };
            cc.vv.gameData.checkAutoPlay(btn, clickFunc);
            btn.on("click", async()=>{
                btn.stopAllActions();
                clickFunc();
            });

        })
    },

    // 再次触发免费
    playTriFreeAgainAnim(freecnt){
        return new Promise(async(success, failed)=>{
            Global.SlotsSoundMgr.playEffect("sound_Kangaroos_pop_window");

            this._node_popup.active = true;
            this._node_tri_free_again.active = true;

            cc.find("spr_kuang/lbl", this._node_tri_free_again).getComponent(cc.Label).string = freecnt;

            await this.playPanelAnim(true, this._node_tri_free_again);

            await cc.vv.gameData.awaitTime(1.5);

            await this.playPanelAnim(false, this._node_tri_free_again);

            this._node_popup.active = false;
            this._node_tri_free_again.active = false;
            success();
        })
    },

    // 结束免费
    playEndFreeAnim(wincoin, freecnt){
        return new Promise(async(success, failed)=>{
            Global.SlotsSoundMgr.playEffect("sound_Kangaroos_pop_window");

            this._node_popup.active = true;
            this._node_end_free.active = true;

            cc.find("spr_kuang/lbl", this._node_end_free).getComponent(cc.Label).string = Global.FormatNumToComma(wincoin);
            cc.find("cnts/lbl", this._node_end_free).getComponent(cc.Label).string = Global.FormatNumToComma(freecnt);

            let btn = cc.find("btn", this._node_end_free);
            btn.off("click");
            btn.getComponent(cc.Button).interactable = true;

            await this.playPanelAnim(true, this._node_end_free);

            let self = this;
            let clickFunc = async()=>{
                Global.SlotsSoundMgr.playEffect("sound_Kangaroos_click_btn");
                btn.getComponent(cc.Button).interactable = false;

                await self.playPanelAnim(false, self._node_end_free);

                self._node_popup.active = false;
                self._node_end_free.active = false;
                success();
            }
            cc.vv.gameData.checkAutoPlay(btn, clickFunc);
            btn.on("click", async()=>{
                btn.stopAllActions();
                clickFunc();
            });
        })
    },


    // 赢的奖池
    playWinJpAnim(wincoin, jpidx){
        return new Promise(async(success, failed)=>{
            Global.SlotsSoundMgr.playEffect("");

            this._node_popup.active = true;
            this._node_win_jp.active = true;

            cc.find("spr_jp", this._node_win_jp).getComponent("ImgSwitchCmp").setIndex(jpidx-2);
            cc.find("spr_kuang/lbl", this._node_win_jp).getComponent(cc.Label).string = Global.FormatNumToComma(wincoin);

            let btn = cc.find("btn", this._node_win_jp);
            btn.off("click");
            btn.getComponent(cc.Button).interactable = true;

            await this.playPanelAnim(true, this._node_win_jp);

            let self = this;
            let clickFunc = async()=>{
                Global.SlotsSoundMgr.playEffect("sound_Kangaroos_click_btn");
                btn.getComponent(cc.Button).interactable = false;

                await self.playPanelAnim(false, self._node_win_jp);

                self._node_popup.active = false;
                self._node_win_jp.active = false;
                success();
            };
            cc.vv.gameData.checkAutoPlay(btn, clickFunc);
            btn.on("click", async()=>{
                btn.stopAllActions();
                clickFunc();
            });
        })
    },



    async playQpAnim(){
        Global.SlotsSoundMgr.playEffect("sound_Kangaroos_run");

        this._node_qp.active = true;
        let spine = cc.find("kangaroo", this._node_qp);
        spine.getComponent(sp.Skeleton).setAnimation(0,"idle2",false);
        // spine.getComponent(sp.Skeleton).setCompleteListener(()=>{
        //     this._node_qp.active = false;
        // })

        await cc.vv.gameData.awaitTime(2);
        this._node_qp.active = false;
    },

    // update (dt) {},
});
